            if (szL <= szR) {
                // Itera pelo lado esquerdo
                // Pares (i, j) com i em [L[u], u - 1] e j em [u, min(R[u], i + K)]
                for (int i = L[u]; i < u; i++) {
                    int low = u;
                    long maxJ = i + k;
                    int high = (maxJ < R[u]) ? (int) maxJ : R[u];
                    if (low <= high) {
                        int c1 = countInRange(posP.get(P[i] + k), low, high);
                        int c2 = countInRange(posM.get(M[i] + k), low, high);
                        int overlap = 0;
                        if (maxJ >= low && maxJ <= high) {
                            if (A[(int) maxJ] == A[i]) {
                                overlap = 1;
                            }
                        }
                        count += (long) c1 + c2 - overlap;
                    }
                }
                // Pares (u, j) com j em [u + 1, min(R[u], u + K)]
                {
                    int low = u + 1;
                    long maxJ = u + k;
                    int high = (maxJ < R[u]) ? (int) maxJ : R[u];
                    if (low <= high) {
                        int c1 = countInRange(posP.get(P[u] + k), low, high);
                        int c2 = countInRange(posM.get(M[u] + k), low, high);
                        int overlap = 0;
                        if (maxJ >= low && maxJ <= high) {
                            if (A[(int) maxJ] == A[u]) {
                                overlap = 1;
                            }
                        }
                        count += (long) c1 + c2 - overlap;
                    }
                }
            } else {
                // Itera pelo lado direito
                // Pares (i, j) com j em [u + 1, R[u]] e i em [max(L[u], j - K), u]
                for (int j = u + 1; j <= R[u]; j++) {
                    long minI = j - k;
                    int low = (minI > L[u]) ? (int) minI : L[u];
                    int high = u;
                    if (low <= high) {
                        int c1 = countInRange(posP.get(P[j] - k), low, high);
                        int c2 = countInRange(posM.get(M[j] - k), low, high);
                        int overlap = 0;
                        if (minI >= low && minI <= high) {
                            if (A[(int) minI] == A[j]) {
                                overlap = 1;
                            }
                        }
                        count += (long) c1 + c2 - overlap;
                    }
                }
                // Pares (i, u) com i em [max(L[u], u - K), u - 1]
                {
                    long minI = u - k;
                    int low = (minI > L[u]) ? (int) minI : L[u];
                    int high = u - 1;
                    if (low <= high) {
                        int c1 = countInRange(posP.get(P[u] - k), low, high);
                        int c2 = countInRange(posM.get(M[u] - k), low, high);
                        int overlap = 0;
                        if (minI >= low && minI <= high) {
                            if (A[(int) minI] == A[u]) {
                                overlap = 1;
                            }
                        }
                        count += (long) c1 + c2 - overlap;
                    }
                }
            }

            C[u] = count;
            totalInitial += count;
        }

        PrintWriter out = new PrintWriter(System.out);
        out.println(totalInitial);

        long current = totalInitial;
        for (int t = 1; t <= q; t++) {
            current -= C[D[t]];
            out.println(current);
        }

        out.flush();
    }
